java
public class UserRepository {
    public void save(User user) {
        // 将 user 对象转换为 JSON 格式字符串
        String userJson = new ObjectMapper().writeValueAsString(user);
        // 将 JSON 格式字符串保存到数据库
        jdbcTemplate.update("INSERT INTO user (user_json) VALUES (?)", userJson);
    }
}
